<?php
/**
 * agreement-pages-test.php — the generated /agreements/ pages keep the
 * contract with /api/agreement-apply.php and /api/agent-directory.php
 * (27 Sep 2026).
 *
 * The six agreement pages and the landing page are generated by
 * tools/agreements/build.js. This suite reads the committed HTML only (no
 * database, no server) and checks what the two APIs and the owner rely on:
 *   - every page is noindex, self-contained (no outside script), and prints
 *     a running footer with "page X / Y" and its document code;
 *   - the online application: the honeypot input name="website" is hidden
 *     off-screen, the API path and the X-CSRF-Token header are the fixed
 *     ones, the client-side required list per type is exactly the API's;
 *   - every input name on a page is one the API accepts (so nothing the
 *     applicant types is silently dropped), and each type carries its own
 *     fields (org: p_rep, p_type, org_*; ind: p_idno, p_idtype, ind_*);
 *   - the signature page carries both parties, two witnesses, the company
 *     seal and the FOR S HARI GLOBAL PVT. LTD. / DIRECTOR / CEO closing;
 *   - the landing page links all six pages and the three older pages, reads
 *     /api/agent-directory.php, keeps the list hidden until it loads, and
 *     never writes API text as HTML.
 *
 *   php tests/agreement-pages-test.php
 */
declare(strict_types=1);

if (PHP_SAPI !== 'cli') {
    http_response_code(403);
    exit('CLI only.');
}

$root = dirname(__DIR__);
$dir = $root . '/agreements';
$PASS = 0;
$FAIL = 0;

function check(string $label, bool $ok, string $extra = ''): void
{
    global $PASS, $FAIL;
    if ($ok) {
        $PASS++;
        echo "  \033[32mPASS\033[0m  {$label}" . ($extra !== '' ? " — {$extra}" : '') . "\n";
    } else {
        $FAIL++;
        echo "  \033[31mFAIL\033[0m  {$label}" . ($extra !== '' ? " — {$extra}" : '') . "\n";
    }
}

/** The field names /api/agreement-apply.php accepts (the fixed contract). */
const API_FIELDS = [
    'a_no', 'a_date', 'a_place', 'co_gst', 'co_email', 'co_sig', 'co_desig', 'p_name', 'p_type', 'p_reg', 'p_tax', 'p_addr',
    'p_office', 'p_phone', 'p_email', 'p_rep', 'p_rep_desig', 'p_rep_phone', 'p_id', 'p_dir_id', 'p_route', 'p_area', 'p_dob',
    'p_occ', 'p_addr2', 'p_idtype', 'p_idno', 'p_pan', 'a_start', 'a_end', 'b_name', 'b_bank', 'b_acc',
    'b_ifsc', 'b_upi', 'org_rate', 'org_pct', 'org_target', 'org_fixed', 'org_day', 'org_dep', 'ind_target',
    'ind_fixed', 'ind_pct', 'ind_dep', 'c31_hours', 'c62_years', 'c73', 'w1_name', 'w1_addr', 'w2_name', 'w2_addr',
    'g1_name', 'g1_id', 'g1_addr', 'g2_name', 'g2_id', 'g2_addr', 'g3_name', 'g3_id', 'g3_addr', 'g4_name', 'g4_id', 'g4_addr',
];
/** The four languages every agreement is printed in (27 Sep 2026: Gujarati added). */
const LANGS = ['ne', 'hi', 'en', 'gu'];
const REQUIRED = [
    'org' => ['p_name', 'p_phone', 'p_area', 'p_rep'],
    'ind' => ['p_name', 'p_phone', 'p_area', 'p_idno', 'p_addr'],
];
const OWN = [
    'org' => ['p_rep', 'p_rep_desig', 'p_rep_phone', 'p_type', 'p_office', 'p_dir_id', 'org_rate', 'org_pct', 'org_target', 'org_fixed', 'org_day', 'org_dep'],
    'ind' => ['p_idno', 'p_idtype', 'p_dob', 'p_occ', 'p_addr2', 'p_pan', 'ind_target', 'ind_fixed', 'ind_pct', 'ind_dep'],
];
const PAGES = ['org' => 'partner-agreement', 'ind' => 'agent-agreement'];

/** The JSON handed to the page script: (function agreementPage(CFG){...})({...}); */
function pageConfig(string $html): ?array
{
    if (!preg_match('~\}\)\((\{.*?\})\);\s*</script>~s', $html, $m)) {
        return null;
    }
    $j = json_decode($m[1], true);
    return is_array($j) ? $j : null;
}

echo "\n=== /agreements/: generated pages keep the API contract ===\n\n";

foreach (PAGES as $type => $base) {
    foreach (LANGS as $lang) {
        $name = "{$base}-{$lang}.html";
        $path = "{$dir}/{$name}";
        if (!is_file($path)) {
            check("{$name} exists", false);
            continue;
        }
        $html = (string) file_get_contents($path);
        echo "  -- {$name}\n";

        check("{$name}: lang=\"{$lang}\" and noindex",
            str_contains($html, "<html lang=\"{$lang}\">") && (bool) preg_match('~<meta name="robots" content="noindex~', $html));
        // 2 Oct 2026: the one script a page may load is our own
        // /assets/js/agreement-live.js (the office's point corrections).
        preg_match_all('~<script\b[^>]*\bsrc="([^"]*)"~i', $html, $ext);
        $outside = array_filter($ext[1], static fn(string $u): bool => !str_starts_with($u, '/assets/js/agreement-live.js'));
        check("{$name}: no outside script", $outside === []);
        check("{$name}: loads the office's point corrections", count($ext[1]) - count($outside) === 1);
        preg_match_all('~<link\b[^>]*href="(https?://[^"]+)"~i', $html, $links);
        $foreign = array_filter($links[1], static fn($u) => !preg_match('~^https://fonts\.(googleapis|gstatic)\.com(/|$)~', $u));
        check("{$name}: only Google Fonts from outside", $foreign === [], implode(' ', $foreign));

        $cfg = pageConfig($html);
        check("{$name}: page config readable", $cfg !== null);
        $cfg = $cfg ?? [];
        check("{$name}: type/lang in config", ($cfg['type'] ?? '') === $type && ($cfg['lang'] ?? '') === $lang);
        check("{$name}: posts to /api/agreement-apply.php", ($cfg['api'] ?? '') === '/api/agreement-apply.php');
        check("{$name}: required list = the API's", ($cfg['req'] ?? null) === REQUIRED[$type], json_encode($cfg['req'] ?? null));
        check("{$name}: \"applied\" message carries {ref}", str_contains((string) ($cfg['ui']['applied'] ?? ''), '{ref}'));
        foreach (['required', 'applyFail', 'applyOffline', 'applying'] as $k) {
            check("{$name}: ui.{$k} present", trim((string) ($cfg['ui'][$k] ?? '')) !== '');
        }
        check("{$name}: X-CSRF-Token header + JSON body",
            str_contains($html, "'X-CSRF-Token': g.j.csrf") && str_contains($html, "'Content-Type': 'application/json'"));
        check("{$name}: body keys type, lang, fields, photo, public_ok, website",
            (bool) preg_match('~type: CFG\.type, lang: CFG\.lang, fields: f, photo: photoData\(\), public_ok: [^,]+, website: ~', $html));

        // honeypot: name="website", off-screen wrapper, not tabbable, never inside "fields"
        check("{$name}: honeypot input name=\"website\" hidden off-screen",
            (bool) preg_match('~<div class="hp" aria-hidden="true">.*?<input type="text" name="website" tabindex="-1" autocomplete="off"~s', $html)
            && (bool) preg_match('~\.hp\{position:absolute!important;left:-10000px!important~', $html));
        check("{$name}: the honeypot is left out of fields", str_contains($html, "return el.name !== 'website';"));
        check("{$name}: application block is screen-only", str_contains($html, '<section class="apply no-print" id="apply"'));
        check("{$name}: public-list consent checkbox", str_contains($html, 'id="pubOk"'));

        // every named control is one the API accepts; this type's own fields are all there
        preg_match_all('~<(?:input|textarea)\b[^>]*\bname="([^"]+)"~', $html, $nm);
        $names = array_values(array_unique($nm[1]));
        // k_* are the office's KYC tick boxes: kept on the phone, never sent
        $unknown = array_values(array_filter(array_diff($names, API_FIELDS, ['website']), static fn($n) => !str_starts_with($n, 'k_')));
        check("{$name}: every input name is an API field", $unknown === [], implode(', ', $unknown));
        $missing = array_values(array_diff(OWN[$type], $names));
        check("{$name}: carries its own fields", $missing === [], implode(', ', $missing));
        $other = OWN[$type === 'org' ? 'ind' : 'org'];
        $leak = array_values(array_intersect(array_diff($other, ['p_id']), $names));
        check("{$name}: no fields of the other type", $leak === [], implode(', ', $leak));
        foreach (REQUIRED[$type] as $r) {
            check("{$name}: {$r} is marked required", (bool) preg_match('~name="' . $r . '"[^>]*aria-required="true"~', $html));
        }

        // print: A4, running footer with page X / Y and the document code
        // 22 Oct 2026: the agent pages are v2.3 (section 14A "Staff and conduct"); partner stays v2.2.
        $code = 'SHG-AGR-' . ($type === 'org' ? 'P' : 'A') . '-' . strtoupper($lang) . ($type === 'org' ? ' v2.2' : ' v2.3');
        check("{$name}: A4 with page X / Y footer",
            str_contains($html, '@page{size:A4;') && str_contains($html, 'counter(page) " / " counter(pages)'));
        check("{$name}: document code {$code} in the footer", str_contains($html, "@bottom-center{content:\"{$code}\""));
        check("{$name}: colour and black-and-white themes", str_contains($html, 'data-theme="colour"') && str_contains($html, 'data-theme="bw"') && str_contains($html, 'html.bw{'));

        // signature page
        check("{$name}: signature page complete",
            str_contains($html, '<div class="sigwrap">') && substr_count($html, 'class="pb') >= 4
            && str_contains($html, 'name="w1_name"') && str_contains($html, 'name="w2_addr"')
            && str_contains($html, 'class="seal"') && str_contains($html, 'class="thumbs"')
            && str_contains($html, 'name="g1_name"') && str_contains($html, 'name="g4_addr"')
            && !str_contains($html, 'DIRECTOR / CEO')
            && str_contains($html, 'www.shreehariglobal.in'));
        check("{$name}: a sent form cannot be sent twice; a timeout says so", str_contains($html, 'U.sentBtn; btn.disabled = true;') && str_contains($html, 'U.applyUnsure'));
        check("{$name}: signature block kept on one page", str_contains($html, '.sigwrap{break-inside:avoid'));
        $secWant = $type === 'org' ? 15 : 16;   // agent v2.3 adds 14A
        check("{$name}: {$secWant} sections, pay terms in the Schedule box",
            substr_count($html, '<h3 class="sh"><span class="no">') === $secWant && substr_count($html, '<div class="sched">') === 1);
    }
}

/* ---------------------------------------------------------------- landing page */
echo "  -- index.html\n";
$ipath = "{$dir}/index.html";
$idx = is_file($ipath) ? (string) file_get_contents($ipath) : '';
check('index.html exists', $idx !== '');
check('index: noindex', (bool) preg_match('~<meta name="robots" content="noindex~', $idx));
foreach (PAGES as $base) {
    foreach (LANGS as $lang) {
        check("index: links {$base}-{$lang}.html", str_contains($idx, "href=\"{$base}-{$lang}.html\""));
    }
}
// 27 Sep 2026 (owner): the "Other pages" card is gone from the agreements page.
foreach (['/agent-agreement/', '/agent-panel.html', '/desk'] as $href) {
    check("index: no longer links {$href}", !str_contains($idx, "href=\"{$href}\""));
}
check('index: reads /api/agent-directory.php', str_contains($idx, '"api":"/api/agent-directory.php"'));
check('index: the list stays hidden until it loads', str_contains($idx, '<section class="card dir" id="dir" hidden>'));
check('index: a failed fetch hides the list', str_contains($idx, "catch(function () { sec.hidden = true; })"));
check('index: API text is written as text, never HTML', !str_contains($idx, 'innerHTML') && str_contains($idx, 'e.textContent = text'));
check('index: only masked-free numbers become tel: links', str_contains($idx, "ph.indexOf('\\u2022') < 0"));
check('index: no outside script', !preg_match('~<script\b[^>]*\bsrc=~i', $idx));

echo "\n  {$PASS} passed, {$FAIL} failed\n\n";
exit($FAIL === 0 ? 0 : 1);
